{"message":{"blocks":[{"is_error":false,"output":"{\n  \"type\": \"text\",\n  \"file\": {\n    \"filePath\": \"\\\\\\\\?\\\\E:\\\\360Downloads\\\\claw-code-main\\\\rust\\\\1\\\\game.js\",\n    \"content\": \"// 游戏常量\\nconst GRID_SIZE = 20;\\nconst CANVAS_WIDTH = 600;\\nconst CANVAS_HEIGHT = 600;\\nconst GRID_WIDTH = CANVAS_WIDTH / GRID_SIZE;\\nconst GRID_HEIGHT = CANVAS_HEIGHT / GRID_SIZE;\\n\\n// 游戏状态\\nlet game = {\\n    snake: [],\\n    food: { x: 0, y: 0 },\\n    direction: 'right',\\n    nextDirection: 'right',\\n    score: 0,\\n    highScore: localStorage.getItem('snakeHighScore') || 0,\\n    gameOver: false,\\n    paused: false,\\n    gameLoop: null,\\n    speed: 150, // 初始速度（毫秒）\\n    difficulty: 'easy'\\n};\\n\\n// DOM元素\\nconst canvas = document.getElementById('game-canvas');\\nconst ctx = canvas.getContext('2d');\\nconst scoreElement = document.getElementById('score');\\nconst highScoreElement = document.getElementById('high-score');\\nconst lengthElement = document.getElementById('length');\\nconst startBtn = document.getElementById('start-btn');\\nconst pauseBtn = document.getElementById('pause-btn');\\nconst resetBtn = document.getElementById('reset-btn');\\nconst restartBtn = document.getElementById('restart-btn');\\nconst gameOverElement = document.getElementById('game-over');\\nconst gamePausedElement = document.getElementById('game-paused');\\nconst finalScoreElement = document.getElementById('final-score');\\nconst difficultyRadios = document.querySelectorAll('input[name=\\\"difficulty\\\"]');\\n\\n// 初始化游戏\\nfunction initGame() {\\n    // 初始化蛇\\n    game.snake = [\\n        { x: 10, y: 10 },\\n        { x: 9, y: 10 },\\n        { x: 8, y: 10 }\\n    ];\\n    \\n    // 生成食物\\n    generateFood();\\n    \\n    // 重置游戏状态\\n    game.direction = 'right';\\n    game.nextDirection = 'right';\\n    game.score = 0;\\n    game.gameOver = false;\\n    game.paused = false;\\n    \\n    // 更新UI\\n    updateScore();\\n    gameOverElement.classList.remove('active');\\n    gamePausedElement.classList.remove('active');\\n    \\n    // 绘制初始状态\\n    draw();\\n}\\n\\n// 生成食物\\nfunction generateFood() {\\n    let foodPosition;\\n    let validPosition = false;\\n    \\n    while (!validPosition) {\\n        foodPosition = {\\n            x: Math.floor(Math.random() * GRID_WIDTH),\\n            y: Math.floor(Math.random() * GRID_HEIGHT)\\n        };\\n        \\n        // 检查食物是否与蛇身重叠\\n        validPosition = !game.snake.some(segment => \\n            segment.x === foodPosition.x && segment.y === foodPosition.y\\n        );\\n    }\\n    \\n    game.food = foodPosition;\\n}\\n\\n// 绘制游戏\\nfunction draw() {\\n    // 清空画布\\n    ctx.fillStyle = '#0f1123';\\n    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);\\n    \\n    // 绘制网格\\n    drawGrid();\\n    \\n    // 绘制蛇\\n    drawSnake();\\n    \\n    // 绘制食物\\n    drawFood();\\n}\\n\\n// 绘制网格\\nfunction drawGrid() {\\n    ctx.strokeStyle = 'rgba(76, 201, 240, 0.1)';\\n    ctx.lineWidth = 1;\\n    \\n    // 绘制垂直线\\n    for (let x = 0; x <= CANVAS_WIDTH; x += GRID_SIZE) {\\n        ctx.beginPath();\\n        ctx.moveTo(x, 0);\\n        ctx.lineTo(x, CANVAS_HEIGHT);\\n        ctx.stroke();\\n    }\\n    \\n    // 绘制水平线\\n    for (let y = 0; y <= CANVAS_HEIGHT; y += GRID_SIZE) {\\n        ctx.beginPath();\\n        ctx.moveTo(0, y);\\n        ctx.lineTo(CANVAS_WIDTH, y);\\n        ctx.stroke();\\n    }\\n}\\n\\n// 绘制蛇\\nfunction drawSnake() {\\n    game.snake.forEach((segment, index) => {\\n        // 蛇头\\n        if (index === 0) {\\n            ctx.fillStyle = '#4cc9f0';\\n            ctx.fillRect(\\n                segment.x * GRID_SIZE, \\n                segment.y * GRID_SIZE, \\n                GRID_SIZE, \\n                GRID_SIZE\\n            );\\n            \\n            // 蛇头边框\\n            ctx.strokeStyle = '#fff';\\n            ctx.lineWidth = 2;\\n            ctx.strokeRect(\\n                segment.x * GRID_SIZE, \\n                segment.y * GRID_SIZE, \\n                GRID_SIZE, \\n                GRID_SIZE\\n            );\\n            \\n            // 绘制眼睛\\n            ctx.fillStyle = '#fff';\\n            let eyeSize = GRID_SIZE / 5;\\n            \\n            // 根据方向调整眼睛位置\\n            let leftEyeX, leftEyeY, rightEyeX, rightEyeY;\\n            \\n            switch(game.direction) {\\n                case 'right':\\n                    leftEyeX = segment.x * GRID_SIZE + GRID_SIZE - eyeSize * 2;\\n                    leftEyeY = segment.y * GRID_SIZE + eyeSize * 2;\\n                    rightEyeX = segment.x * GRID_SIZE + GRID_SIZE - eyeSize * 2;\\n                    rightEyeY = segment.y * GRID_SIZE + GRID_SIZE - eyeSize * 3;\\n                    break;\\n                case 'left':\\n                    leftEyeX = segment.x * GRID_SIZE + eyeSize;\\n                    leftEyeY = segment.y * GRID_SIZE + eyeSize * 2;\\n                    rightEyeX = segment.x * GRID_SIZE + eyeSize;\\n                    rightEyeY = segment.y * GRID_SIZE + GRID_SIZE - eyeSize * 3;\\n                    break;\\n                case 'up':\\n                    leftEyeX = segment.x * GRID_SIZE + eyeSize * 2;\\n                    leftEyeY = segment.y * GRID_SIZE + eyeSize;\\n                    rightEyeX = segment.x * GRID_SIZE + GRID_SIZE - eyeSize * 3;\\n                    rightEyeY = segment.y * GRID_SIZE + eyeSize;\\n                    break;\\n                case 'down':\\n                    leftEyeX = segment.x * GRID_SIZE + eyeSize * 2;\\n                    leftEyeY = segment.y * GRID_SIZE + GRID_SIZE - eyeSize * 2;\\n                    rightEyeX = segment.x * GRID_SIZE + GRID_SIZE - eyeSize * 3;\\n                    rightEyeY = segment.y * GRID_SIZE + GRID_SIZE - eyeSize * 2;\\n                    break;\\n            }\\n            \\n            ctx.fillRect(leftEyeX, leftEyeY, eyeSize, eyeSize);\\n            ctx.fillRect(rightEyeX, rightEyeY, eyeSize, eyeSize);\\n            \\n            // 瞳孔\\n            ctx.fillStyle = '#000';\\n            ctx.fillRect(leftEyeX + eyeSize/4, leftEyeY + eyeSize/4, eyeSize/2, eyeSize/2);\\n            ctx.fillRect(rightEyeX + eyeSize/4, rightEyeY + eyeSize/4, eyeSize/2, eyeSize/2);\\n        } \\n        // 蛇身\\n        else {\\n            // 渐变颜色\\n            const gradient = ctx.createLinearGradient(\\n                segment.x * GRID_SIZE, \\n                segment.y * GRID_SIZE, \\n                segment.x * GRID_SIZE + GRID_SIZE, \\n                segment.y * GRID_SIZE + GRID_SIZE\\n            );\\n            \\n            gradient.addColorStop(0, '#4361ee');\\n            gradient.addColorStop(1, '#3a0ca3');\\n            \\n            ctx.fillStyle = gradient;\\n            ctx.fillRect(\\n                segment.x * GRID_SIZE, \\n                segment.y * GRID_SIZE, \\n                GRID_SIZE, \\n                GRID_SIZE\\n            );\\n            \\n            // 蛇身边框\\n            ctx.strokeStyle = '#4cc9f0';\\n            ctx.lineWidth = 1;\\n            ctx.strokeRect(\\n                segment.x * GRID_SIZE, \\n                segment.y * GRID_SIZE, \\n                GRID_SIZE, \\n                GRID_SIZE\\n            );\\n        }\\n    });\\n}\\n\\n// 绘制食物\\nfunction drawFood() {\\n    // 创建径向渐变\\n    const gradient = ctx.createRadialGradient(\\n        game.food.x * GRID_SIZE + GRID_SIZE / 2,\\n        game.food.y * GRID_SIZE + GRID_SIZE / 2,\\n        0,\\n        game.food.x * GRID_SIZE + GRID_SIZE / 2,\\n        game.food.y * GRID_SIZE + GRID_SIZE / 2,\\n        GRID_SIZE / 2\\n    );\\n    \\n    gradient.addColorStop(0, '#ff0000');\\n    gradient.addColorStop(0.7, '#cc0000');\\n    gradient.addColorStop(1, '#990000');\\n    \\n    ctx.fillStyle = gradient;\\n    ctx.beginPath();\\n    ctx.arc(\\n        game.food.x * GRID_SIZE + GRID_SIZE / 2,\\n        game.food.y * GRID_SIZE + GRID_SIZE / 2,\\n        GRID_SIZE / 2 - 2,\\n        0,\\n        Math.PI * 2\\n    );\\n    ctx.fill();\\n    \\n    // 食物高光\\n    ctx.fillStyle = 'rgba(255, 255, 255, 0.3)';\\n    ctx.beginPath();\\n    ctx.arc(\\n        game.food.x * GRID_SIZE + GRID_SIZE / 3,\\n        game.food.y * GRID_SIZE + GRID_SIZE / 3,\\n        GRID_SIZE / 6,\\n        0,\\n        Math.PI * 2\\n    );\\n    ctx.fill();\\n}\\n\\n// 更新游戏状态\\nfunction update() {\\n    if (game.gameOver || game.paused) return;\\n    \\n    // 更新方向\\n    game.direction = game.nextDirection;\\n    \\n    // 计算新的蛇头位置\\n    const head = { ...game.snake[0] };\\n    \\n    switch (game.direction) {\\n        case 'up':\\n            head.y -= 1;\\n            break;\\n        case 'down':\\n            head.y += 1;\\n            break;\\n        case 'left':\\n            head.x -= 1;\\n            break;\\n        case 'right':\\n            head.x += 1;\\n            break;\\n    }\\n    \\n    // 检查碰撞\\n    if (checkCollision(head)) {\\n        gameOver();\\n        return;\\n    }\\n    \\n    // 添加新的蛇头\\n    game.snake.unshift(head);\\n    \\n    // 检查是否吃到食物\\n    if (head.x === game.food.x && head.y === game.food.y) {\\n        // 增加分数\\n        game.score += 1;\\n        \\n        // 更新最高分\\n        if (game.score > game.highScore) {\\n            game.highScore = game.score;\\n            localStorage.setItem('snakeHighScore', game.highScore);\\n        }\\n        \\n        // 更新UI\\n        updateScore();\\n        \\n        // 生成新食物\\n        generateFood();\\n        \\n        // 根据难度调整速度\\n        adjustSpeed();\\n    } else {\\n        // 如果没有吃到食物，移除蛇尾\\n        game.snake.pop();\\n    }\\n    \\n    // 重新绘制\\n    draw();\\n}\\n\\n// 检查碰撞\\nfunction checkCollision(head) {\\n    // 检查墙壁碰撞\\n    if (\\n        head.x < 0 || \\n        head.x >= GRID_WIDTH || \\n        head.y < 0 || \\n        head.y >= GRID_HEIGHT\\n    ) {\\n        return true;\\n    }\\n    \\n    // 检查自身碰撞\\n    for (let i = 0; i < game.snake.length; i++) {\\n        if (game.snake[i].x === head.x && game.snake[i].y === head.y) {\\n            return true;\\n        }\\n    }\\n    \\n    return false;\\n}\\n\\n// 游戏结束\\nfunction gameOver() {\\n    game.gameOver = true;\\n    clearInterval(game.gameLoop);\\n    \\n    // 显示游戏结束界面\\n    finalScoreElement.textContent = `得分: ${game.score}`;\\n    gameOverElement.classList.add('active');\\n    \\n    // 添加动画效果\\n    gameOverElement.classList.add('pulse');\\n    setTimeout(() => {\\n        gameOverElement.classList.remove('pulse');\\n    }, 500);\\n}\\n\\n// 更新分数显示\\nfunction updateScore() {\\n    scoreElement.textContent = game.score;\\n    highScoreElement.textContent = game.highScore;\\n    lengthElement.textContent = game.snake.length;\\n    \\n    // 添加动画效果\\n    scoreElement.classList.add('pulse');\\n    setTimeout(() => {\\n        scoreElement.classList.remove('pulse');\\n    }, 300);\\n}\\n\\n// 根据难度调整速度\\nfunction adjustSpeed() {\\n    switch (game.difficulty) {\\n        case 'easy':\\n            game.speed = Math.max(100, 150 - Math.floor(game.score / 5) * 10);\\n            break;\\n        case 'medium':\\n            game.speed = Math.max(80, 120 - Math.floor(game.score / 5) * 10);\\n            break;\\n        case 'hard':\\n            game.speed = Math.max(60, 100 - Math.floor(game.score / 5) * 10);\\n            break;\\n    }\\n    \\n    // 如果游戏正在运行，重新设置游戏循环\\n    if (game.gameLoop) {\\n        clearInterval(game.gameLoop);\\n        game.gameLoop = setInterval(update, game.speed);\\n    }\\n}\\n\\n// 开始游戏\\nfunction startGame() {\\n    if (game.gameLoop) {\\n        clearInterval(game.gameLoop);\\n    }\\n    \\n    game.paused = false;\\n    gamePausedElement.classList.remove('active');\\n    \\n    game.gameLoop = setInterval(update, game.speed);\\n    startBtn.disabled = true;\\n    pauseBtn.disabled = false;\\n}\\n\\n// 暂停游戏\\nfunction pauseGame() {\\n    if (game.gameOver) return;\\n    \\n    game.paused = !game.paused;\\n    \\n    if (game.paused) {\\n        clearInterval(game.gameLoop);\\n        gamePausedElement.classList.add('active');\\n        pauseBtn.innerHTML = '<i class=\\\"fas fa-play\\\"></i> 继续';\\n    } else {\\n        game.gameLoop = setInterval(update, game.speed);\\n        gamePausedElement.classList.remove('active');\\n        pauseBtn.innerHTML = '<i class=\\\"fas fa-pause\\\"></i> 暂停';\\n    }\\n}\\n\\n// 重置游戏\\nfunction resetGame() {\\n    clearInterval(game.gameLoop);\\n    game.gameLoop = null;\\n    \\n    // 获取当前难度设置\\n    const selectedDifficulty = document.querySelector('input[name=\\\"difficulty\\\"]:checked').value;\\n    game.difficulty = selectedDifficulty;\\n    \\n    // 根据难度设置初始速度\\n    switch (selectedDifficulty) {\\n        case 'easy':\\n            game.speed = 150;\\n            break;\\n        case 'medium':\\n            game.speed = 120;\\n            break;\\n        case 'hard':\\n            game.speed = 100;\\n            break;\\n    }\\n    \\n    initGame();\\n    startBtn.disabled = false;\\n    pauseBtn.disabled = true;\\n    pauseBtn.innerHTML = '<i class=\\\"fas fa-pause\\\"></i> 暂停';\\n    gamePausedElement.classList.remove('active');\\n}\\n\\n// 键盘控制\\nfunction handleKeyDown(event) {\\n    switch (event.key) {\\n        case 'ArrowUp':\\n            if (game.direction !== 'down') {\\n                game.nextDirection = 'up';\\n            }\\n            break;\\n        case 'ArrowDown':\\n            if (game.direction !== 'up') {\\n                game.nextDirection = 'down';\\n            }\\n            break;\\n        case 'ArrowLeft':\\n            if (game.direction !== 'right') {\\n                game.nextDirection = 'left';\\n            }\\n            break;\\n        case 'ArrowRight':\\n            if (game.direction !== 'left') {\\n                game.nextDirection = 'right';\\n            }\\n            break;\\n        case ' ':\\n        case 'Spacebar':\\n            event.preventDefault();\\n            if (game.gameLoop) {\\n                pauseGame();\\n            }\\n            break;\\n    