px 15px rgba(247, 37, 133, 0.4);\\n}\\n\\n/* 难度设置 */\\n.difficulty h3 {\\n    font-size: 1.3rem;\\n    margin-bottom: 20px;\\n    color: #4cc9f0;\\n    display: flex;\\n    align-items: center;\\n    gap: 10px;\\n}\\n\\n.difficulty-options {\\n    display: flex;\\n    flex-direction: column;\\n    gap: 15px;\\n}\\n\\n.difficulty-option {\\n    display: flex;\\n    align-items: center;\\n    gap: 15px;\\n    padding: 15px;\\n    background: rgba(50, 50, 70, 0.6);\\n    border-radius: 10px;\\n    cursor: pointer;\\n    transition: all 0.3s ease;\\n    border: 2px solid transparent;\\n}\\n\\n.difficulty-option:hover {\\n    background: rgba(60, 60, 80, 0.8);\\n    border-color: #4cc9f0;\\n}\\n\\n.difficulty-option input[type=\\\"radio\\\"] {\\n    width: 20px;\\n    height: 20px;\\n    accent-color: #4cc9f0;\\n}\\n\\n.difficulty-label {\\n    font-size: 1.1rem;\\n    font-weight: 600;\\n    color: #fff;\\n}\\n\\n/* 游戏画布容器 */\\n.game-container {\\n    position: relative;\\n    display: flex;\\n    justify-content: center;\\n    align-items: center;\\n}\\n\\n#game-canvas {\\n    background: #0f1123;\\n    border-radius: 10px;\\n    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);\\n    border: 3px solid #4cc9f0;\\n}\\n\\n/* 游戏结束和暂停界面 */\\n.game-over, .game-paused {\\n    position: absolute;\\n    top: 0;\\n    left: 0;\\n    width: 100%;\\n    height: 100%;\\n    background: rgba(15, 17, 35, 0.95);\\n    display: flex;\\n    flex-direction: column;\\n    justify-content: center;\\n    align-items: center;\\n    border-radius: 10px;\\n    z-index: 10;\\n    opacity: 0;\\n    pointer-events: none;\\n    transition: opacity 0.3s ease;\\n}\\n\\n.game-over.active, .game-paused.active {\\n    opacity: 1;\\n    pointer-events: all;\\n}\\n\\n.game-over h2, .game-paused h2 {\\n    font-size: 3rem;\\n    margin-bottom: 20px;\\n    color: #f72585;\\n    text-shadow: 0 0 10px rgba(247, 37, 133, 0.5);\\n}\\n\\n.game-paused h2 {\\n    color: #4cc9f0;\\n    text-shadow: 0 0 10px rgba(76, 201, 240, 0.5);\\n}\\n\\n.game-over p {\\n    font-size: 1.8rem;\\n    margin-bottom: 30px;\\n    color: #fff;\\n}\\n\\n.game-paused p {\\n    font-size: 1.5rem;\\n    color: #b8b8d1;\\n}\\n\\n/* 游戏说明 */\\n.instructions {\\n    background: rgba(40, 40, 60, 0.8);\\n    border-radius: 15px;\\n    padding: 25px;\\n    box-shadow: 0 8px 20px rgba(0, 0, 0, 0.3);\\n}\\n\\n.instructions h3 {\\n    font-size: 1.3rem;\\n    margin-bottom: 20px;\\n    color: #4cc9f0;\\n    display: flex;\\n    align-items: center;\\n    gap: 10px;\\n}\\n\\n.instructions ul {\\n    list-style: none;\\n}\\n\\n.instructions li {\\n    margin-bottom: 15px;\\n    padding: 12px 15px;\\n    background: rgba(50, 50, 70, 0.6);\\n    border-radius: 8px;\\n    border-left: 4px solid #4361ee;\\n    transition: all 0.3s ease;\\n}\\n\\n.instructions li:hover {\\n    background: rgba(60, 60, 80, 0.8);\\n    transform: translateX(5px);\\n}\\n\\n.instructions li i {\\n    width: 25px;\\n    color: #4cc9f0;\\n    margin-right: 10px;\\n}\\n\\n.instructions li strong {\\n    color: #fff;\\n    margin-right: 5px;\\n}\\n\\n/* 页脚 */\\nfooter {\\n    text-align: center;\\n    padding-top: 20px;\\n    border-top: 1px solid #4cc9f0;\\n    color: #b8b8d1;\\n    font-size: 0.9rem;\\n}\\n\\n/* 响应式设计 */\\n@media (max-width: 768px) {\\n    .container {\\n        padding: 15px;\\n    }\\n    \\n    header h1 {\\n        font-size: 2rem;\\n        flex-direction: column;\\n        gap: 10px;\\n    }\\n    \\n    .game-area {\\n        gap: 20px;\\n    }\\n    \\n    #game-canvas {\\n        width: 95vw;\\n        height: 95vw;\\n        max-width: 500px;\\n        max-height: 500px;\\n    }\\n    \\n    .game-info, .instructions {\\n        padding: 20px;\\n    }\\n    \\n    .score-value {\\n        font-size: 2rem;\\n    }\\n    \\n    .btn {\\n        padding: 12px 20px;\\n        font-size: 1rem;\\n    }\\n}\\n\\n/* 动画效果 */\\n@keyframes pulse {\\n    0% { transform: scale(1); }\\n    50% { transform: scale(1.05); }\\n    1