{"message":{"blocks":[{"is_error":false,"output":"{\n  \"type\": \"text\",\n  \"file\": {\n    \"filePath\": \"\\\\\\\\?\\\\E:\\\\360Downloads\\\\claw-code-main\\\\rust\\\\1\\\\game.js\",\n    \"content\": \"// 游戏常量\\nconst GRID_SIZE = 20;\\nconst CANVAS_WIDTH = 600;\\nconst CANVAS_HEIGHT = 600;\\nconst GRID_WIDTH = CANVAS_WIDTH / GRID_SIZE;\\nconst GRID_HEIGHT = CANVAS_HEIGHT / GRID_SIZE;\\n\\n// 游戏状态\\nlet game = {\\n    snake: [],\\n    food: { x: 0, y: 0 },\\n    direction: 'right',\\n    nextDirection: 'right',\\n    score: 0,\\n    highScore: localStorage.getItem('snakeHighScore') || 0,\\n    gameOver: false,\\n    paused: false,\\n    gameLoop: null,\\n    speed: 150, // 初始速度（毫秒）\\n    difficulty: 'easy'\\n};\\n\\n// DOM元素\\nconst canvas = document.getElementById('game-canvas');\\nconst ctx = canvas.getContext('2d');\\nconst scoreElement = document.getElementById('score');\\nconst highScoreElement = document.getElementById('high-score');\\nconst lengthElement = document.getElementById('length');\\nconst startBtn = document.getElementById('start-btn');\\nconst pauseBtn = document.getElementById('pause-btn');\\nconst resetBtn = document.getElementById('reset-btn');\\nconst restartBtn = document.getElementById('restart-btn');\\nconst gameOverElement = document.getElementById('game-over');\\nconst gamePausedElement = document.getElementById('game-paused');\\nconst finalScoreElement = document.getElementById('final-score');\\nconst difficultyRadios = document.querySelectorAll('input[name=\\\"difficulty\\\"]');\\n\\n// 初始化游戏\\nfunction initGame() {\\n    // 初始化蛇\\n    game.snake = [\\n        { x: 10, y: 10 },\\n        { x: 9, y: 10 },\\n        { x: 8, y: 10 }\\n    ];\\n    \\n    // 生成食物\\n    generateFood();\\n    \\n    // 重置游戏状态\\n    game.direction = 'right';\\n    game.nextDirection = 'right';\\n    game.score = 0;\\n    game.gameOver = false;\\n    game.paused = false;\\n    \\n    // 更新UI\\n    updateScore();\\n    gameOverElement.classList.remove('activ